
import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { blogApi } from '../api/blog';
import { BlogPost, PostVisibility } from '../types';
import { 
  ArrowLeft, Save, Eye, Edit3, Image as ImageIcon, 
  Tag, Loader2, Send, CheckCircle, Info, FileText
} from 'lucide-react';
import { useAuth } from '../context/AuthContext';
import { SafeContentRenderer } from '../components/SafeContentRenderer';

const BlogEditor: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { user } = useAuth();
  
  const [isPreview, setIsPreview] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  
  const [formData, setFormData] = useState({
    title: '',
    summary: '',
    content: '',
    coverImageUrl: '',
    tags: '',
    visibility: PostVisibility.DRAFT
  });

  useEffect(() => {
    if (id) {
      setIsLoading(true);
      blogApi.getById(id).then(post => {
        if (post) {
          setFormData({
            title: post.title,
            summary: post.summary,
            content: post.content || post.contentRaw || '',
            coverImageUrl: post.coverImageUrl,
            tags: post.tags.join(', '),
            visibility: post.visibility
          });
        }
        setIsLoading(false);
      });
    }
  }, [id]);

  const handleSave = async (e: React.FormEvent, publish = false) => {
    e.preventDefault();
    setIsSubmitting(true);
    
    const payload: Partial<BlogPost> = {
      ...formData,
      tags: formData.tags.split(',').map(t => t.trim()).filter(t => t !== ''),
      visibility: publish ? PostVisibility.PENDING : formData.visibility
    };

    try {
      if (id) {
        await blogApi.update(id, payload);
      } else {
        await blogApi.create(payload);
      }
      navigate('/dashboard');
    } catch (error) {
      console.error(error);
    } finally {
      setIsSubmitting(false);
    }
  };

  if (isLoading) return <div className="min-h-screen pt-20 flex items-center justify-center"><Loader2 className="animate-spin text-emerald-600" size={40}/></div>;

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 pt-32 pb-20">
      <div className="max-w-5xl mx-auto px-4">
        <header className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-10">
          <div className="flex items-center gap-4">
            <button onClick={() => navigate('/dashboard')} className="p-3 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors text-slate-500 shadow-sm">
                <ArrowLeft size={20} />
            </button>
            <div>
                <h1 className="text-2xl font-black text-slate-900 dark:text-white uppercase tracking-tight">{id ? 'Edit Article' : 'Draft New Story'}</h1>
                <p className="text-xs font-bold text-slate-500 uppercase tracking-widest">Creator Studio</p>
            </div>
          </div>

          <div className="flex items-center gap-3 w-full md:w-auto">
            <button 
                onClick={() => setIsPreview(!isPreview)}
                className="flex-1 md:flex-none px-5 py-2.5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl font-bold text-sm hover:bg-slate-50 dark:hover:bg-slate-800 transition-all flex items-center justify-center gap-2"
            >
                {isPreview ? <><Edit3 size={16}/> Edit</> : <><Eye size={16}/> Preview</>}
            </button>
            <button 
                onClick={(e) => handleSave(e, true)}
                disabled={isSubmitting}
                className="flex-1 md:flex-none px-6 py-2.5 bg-emerald-600 text-white rounded-xl font-bold text-sm hover:bg-emerald-700 transition-all shadow-lg shadow-emerald-600/20 flex items-center justify-center gap-2 disabled:opacity-50"
            >
                {isSubmitting ? <Loader2 className="animate-spin" size={16}/> : <Send size={16}/>}
                Submit for Review
            </button>
          </div>
        </header>

        <AnimatePresence mode="wait">
            {!isPreview ? (
                <motion.form 
                    key="editor"
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: -10 }}
                    className="space-y-6"
                >
                    <div className="bg-white dark:bg-slate-900 p-8 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm space-y-6">
                        <div>
                            <label className="block text-[10px] font-black uppercase text-slate-500 mb-2 tracking-widest pl-1">Article Title</label>
                            <input 
                                type="text" 
                                value={formData.title}
                                onChange={e => setFormData({...formData, title: e.target.value})}
                                className="w-full bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-2xl px-6 py-4 outline-none focus:ring-2 focus:ring-emerald-500 dark:text-white text-xl font-bold"
                                placeholder="Enter an engaging title..."
                            />
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div>
                                <label className="block text-[10px] font-black uppercase text-slate-500 mb-2 tracking-widest pl-1">Cover Image URL</label>
                                <div className="relative">
                                    <ImageIcon className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18}/>
                                    <input 
                                        type="text" 
                                        value={formData.coverImageUrl}
                                        onChange={e => setFormData({...formData, coverImageUrl: e.target.value})}
                                        className="w-full bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-2xl pl-12 pr-6 py-3 outline-none focus:ring-2 focus:ring-emerald-500 dark:text-white"
                                        placeholder="https://..."
                                    />
                                </div>
                            </div>
                            <div>
                                <label className="block text-[10px] font-black uppercase text-slate-500 mb-2 tracking-widest pl-1">Tags (Comma separated)</label>
                                <div className="relative">
                                    <Tag className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18}/>
                                    <input 
                                        type="text" 
                                        value={formData.tags}
                                        onChange={e => setFormData({...formData, tags: e.target.value})}
                                        className="w-full bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-2xl pl-12 pr-6 py-3 outline-none focus:ring-2 focus:ring-emerald-500 dark:text-white"
                                        placeholder="react, trading, web3"
                                    />
                                </div>
                            </div>
                        </div>

                        <div>
                            <label className="block text-[10px] font-black uppercase text-slate-500 mb-2 tracking-widest pl-1">Short Summary</label>
                            <textarea 
                                rows={2}
                                value={formData.summary}
                                onChange={e => setFormData({...formData, summary: e.target.value})}
                                className="w-full bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-2xl px-6 py-4 outline-none focus:ring-2 focus:ring-emerald-500 dark:text-white resize-none text-sm"
                                placeholder="A brief hook for your readers..."
                            />
                        </div>

                        <div>
                            <div className="flex items-center justify-between mb-2 pl-1">
                                <label className="block text-[10px] font-black uppercase text-slate-500 tracking-widest">Main Content (HTML/Rich Text)</label>
                                <div className="flex items-center gap-1.5 text-xs text-slate-400">
                                    <Info size={12}/> Use standard HTML tags
                                </div>
                            </div>
                            <textarea 
                                rows={15}
                                value={formData.content}
                                onChange={e => setFormData({...formData, content: e.target.value})}
                                className="w-full bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-2xl px-6 py-6 outline-none focus:ring-2 focus:ring-emerald-500 dark:text-white font-mono text-sm leading-relaxed"
                                placeholder="Write your story here... HTML tags like <p>, <h2>, <pre><code> are supported."
                            />
                        </div>
                    </div>
                </motion.form>
            ) : (
                <motion.div 
                    key="preview"
                    initial={{ opacity: 0, scale: 0.98 }}
                    animate={{ opacity: 1, scale: 1 }}
                    exit={{ opacity: 0, scale: 0.98 }}
                    className="bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-xl overflow-hidden"
                >
                    <div className="bg-slate-50 dark:bg-slate-800/50 p-4 border-b border-slate-200 dark:border-slate-800 flex items-center gap-2">
                        <FileText size={16} className="text-emerald-500" />
                        <span className="text-xs font-black uppercase text-slate-500 tracking-widest">Live View Mode</span>
                    </div>
                    <div className="p-8 md:p-12">
                        <h2 className="text-4xl md:text-5xl font-black text-slate-900 dark:text-white mb-8 leading-tight tracking-tighter">
                            {formData.title || 'Your Article Title'}
                        </h2>
                        <div className="prose dark:prose-invert max-w-none">
                            <SafeContentRenderer content={formData.content} title={formData.title} />
                        </div>
                    </div>
                </motion.div>
            )}
        </AnimatePresence>
      </div>
    </div>
  );
};

export default BlogEditor;
